// Vendored workflow engine: generated by scripts/sync-workflow-engine.mjs, never edited by hand. Source, commit and local patches: lib/workflow-engine/UPSTREAM.json
/**
 * Minimal MongoDB-style query matcher for "$mongo_expr" placeholders in the DSL.
 * Supports dot paths and the operators the diff engine needs:
 *   $eq $ne $gt $gte $lt $lte $in $nin $exists $regex $and $or $not $nor
 * ($and/$or/$nor work both at the top level and nested inside a value query).
 * Plain { path: value } entries are implicit $eq. Unknown operators throw —
 * dsl/validate.ts rejects them at authoring time so they never reach a route.
 */
export type Doc = Record<string, unknown>;

export function get(doc: unknown, path: string): unknown {
  let cur: unknown = doc;
  for (const part of path.split('.')) {
    if (cur === null || typeof cur !== 'object') return undefined;
    cur = (cur as Doc)[part];
  }
  return cur;
}

function eq(a: unknown, b: unknown): boolean {
  if (Array.isArray(a) && !Array.isArray(b)) return a.some((x) => eq(x, b));
  return JSON.stringify(a) === JSON.stringify(b);
}

function matchValue(actual: unknown, expected: unknown): boolean {
  if (
    expected !== null &&
    typeof expected === 'object' &&
    !Array.isArray(expected) &&
    Object.keys(expected).some((k) => k.startsWith('$'))
  ) {
    return Object.entries(expected as Doc).every(([op, arg]) => {
      switch (op) {
        case '$eq':
          return eq(actual, arg);
        case '$ne':
          return !eq(actual, arg);
        case '$gt':
          return (actual as number) > (arg as number);
        case '$gte':
          return (actual as number) >= (arg as number);
        case '$lt':
          return (actual as number) < (arg as number);
        case '$lte':
          return (actual as number) <= (arg as number);
        case '$in':
          return Array.isArray(arg) && arg.some((x) => eq(actual, x));
        case '$nin':
          return Array.isArray(arg) && !arg.some((x) => eq(actual, x));
        case '$exists':
          return (actual !== undefined) === Boolean(arg);
        case '$regex':
          return typeof actual === 'string' && new RegExp(String(arg)).test(actual);
        case '$not':
          return !matchValue(actual, arg);
        case '$and':
          return Array.isArray(arg) && arg.every((sub) => matchValue(actual, sub));
        case '$or':
          return Array.isArray(arg) && arg.some((sub) => matchValue(actual, sub));
        case '$nor':
          return Array.isArray(arg) && !arg.some((sub) => matchValue(actual, sub));
        default:
          throw new Error(`unsupported operator ${op}`);
      }
    });
  }
  return eq(actual, expected);
}

/**
 * Substitutes `{"$object": "<path>"}` value tokens out of a directory query,
 * reading `<path>` from the attached object's data. This is what lets an
 * assignee query name the case it is routing — "the senior viewer of THIS
 * case's originating unit" rather than "a senior viewer".
 *
 * Fails CLOSED. An unresolved path is reported, never dropped: dropping the
 * clause would widen the query from one person to every directory user with
 * that role, and in a maker-checker chain routing to the wrong reviewer is
 * worse than routing to nobody. Callers refuse to resolve when `unresolved` is
 * non-empty, so the substituted value on that branch is never consulted.
 *
 * A query containing no token is returned structurally identical, so every
 * existing workflow takes the same path it always did.
 */
export function substituteObject(
  query: unknown,
  data: Record<string, unknown>,
): { query: unknown; unresolved: string[] } {
  const unresolved: string[] = [];
  const walk = (node: unknown): unknown => {
    if (Array.isArray(node)) return node.map(walk);
    if (node === null || typeof node !== 'object') return node;
    const entries = Object.entries(node as Doc);
    if (entries.length === 1 && entries[0][0] === '$object') {
      const path = entries[0][1];
      if (typeof path !== 'string' || path === '') {
        unresolved.push(JSON.stringify(path));
        return UNRESOLVED;
      }
      const value = getOwn(data, path);
      // Only a usable scalar counts as resolved, and the rejected cases are
      // rejected for concrete reasons, not tidiness:
      //   undefined  the object simply does not carry the field
      //   null / ''  Directory.query DROPS clauses with these values, which is
      //              precisely the widening this must not do
      //   object     object data is caller-supplied, so a value like
      //              {"$ne": "x"} would splice attacker-chosen OPERATORS into
      //              the query and match everyone holding the role
      //   array      exact-array equality is never what an author means here;
      //              `$in` with explicit values says it directly
      // `0` and `false` are kept: they are ordinary values a field may hold.
      if (typeof value !== 'string' && typeof value !== 'number' && typeof value !== 'boolean') {
        unresolved.push(path);
        return UNRESOLVED;
      }
      if (value === '') {
        unresolved.push(path);
        return UNRESOLVED;
      }
      return value;
    }
    return Object.fromEntries(entries.map(([k, v]) => [k, walk(v)]));
  };
  return { query: walk(query), unresolved };
}

/**
 * Placeholder left where a token could not be resolved. Callers refuse on a
 * non-empty `unresolved`, so this is belt-and-braces — but it must not be a
 * value the matcher would treat as "no constraint", because the whole point of
 * the change is that a missed check must not widen a query.
 *
 * Two rejected candidates, both of which widen:
 *   null      Directory.query STRIPS null clauses — the clause vanishes
 *   a symbol  eq() compares by JSON.stringify, and a symbol stringifies to
 *             undefined, so it matched every record MISSING the field — a
 *             populated set, since directory records routinely omit fields
 * `$in: []` asks "is the value one of none", which is false for every record
 * including those missing the field. It survives Directory.query's stripping
 * (it is neither null nor '') and needs no special case in the matcher.
 */
export const UNRESOLVED = { $in: [] as unknown[] };

/**
 * Dot-path lookup over OWN properties only. `get()` reaches inherited members,
 * so `{"$object": "toString"}` resolved to Object.prototype.toString and read
 * as "found" rather than missing.
 *
 * Honest about what this buys today: with the scalar check above in place, no
 * mutation of this function alone turns a test red — every inherited member
 * reachable on plain JSON data is a function or an object, which the scalar
 * check already rejects. It is kept as the structural guarantee rather than an
 * incidental one: "inherited members are not object data" should not depend on
 * every such member happening to be non-scalar, and widening the accepted
 * types later must not silently re-open this.
 */
function getOwn(doc: unknown, path: string): unknown {
  let cur: unknown = doc;
  for (const part of path.split('.')) {
    if (cur === null || typeof cur !== 'object') return undefined;
    if (!Object.prototype.hasOwnProperty.call(cur, part)) return undefined;
    cur = (cur as Doc)[part];
  }
  return cur;
}

export function matches(doc: unknown, query: unknown): boolean {
  if (query === undefined || query === null) return true;
  if (typeof query !== 'object' || Array.isArray(query)) {
    throw new Error('query must be an object');
  }
  return Object.entries(query as Doc).every(([key, expected]) => {
    switch (key) {
      case '$and':
        return (expected as unknown[]).every((q) => matches(doc, q));
      case '$or':
        return (expected as unknown[]).some((q) => matches(doc, q));
      case '$nor':
        return !(expected as unknown[]).some((q) => matches(doc, q));
      case '$not':
        return !matches(doc, expected);
      default:
        return matchValue(get(doc, key), expected);
    }
  });
}
